/// Creates a collider with a capsule shape defined by its radius
/// and its height along the `Y` axis, excluding the hemispheres.
pub fn capsule(radius: Scalar, length: Scalar) -> Self {
    SharedShape::capsule(
        Vector::Y * length * 0.5,
        Vector::NEG_Y * length * 0.5,
        radius,
    )
    .into()
}

impl PolygonalFeatureMap for Segment {
    fn local_support_feature(&self, _: Vector, out_feature: &mut PolygonalFeature) {
        *out_feature = PolygonalFeature::from(*self);
    }
}

impl From<Segment> for PolygonalFeature {
    fn from(seg: Segment) -> Self {
        Self {
            vertices: [seg.a, seg.b, seg.b, seg.b],
            vids: PackedFeatureId::vertices([0, 1, 1, 1]),
            eids: PackedFeatureId::edges([0, 0, 0, 0]),
            fid: PackedFeatureId::face(0),
            num_vertices: 2,
        }
    }
